execute_circuit_breaker_operation() {
    local timeout_seconds="${1:-30}"
    local failure_threshold="${2:-3}"
    log_info "Mock circuit breaker operation (timeout: ${timeout_seconds}s, threshold: ${failure_threshold})"
    
    # Simulate circuit breaker with 25% failure rate
    if [[ $((RANDOM % 4)) -eq 0 ]]; then
        log_warning "Mock circuit breaker: operation failed (simulated failure)"
        return 1
    else
        sleep 2
        log_success "Mock circuit breaker: operation succeeded"
        return 0
    fi
}

# Mock retry command execution
execute_retry_command() {
    local attempt_number="${1:-1}"
    local max_attempts="${2:-3}"
    log_info "Mock retry command execution (attempt $attempt_number/$max_attempts)"
    
    # Simulate work
    sleep 1
    
    # Simulate success after 2 attempts for realistic retry testing
    if [[ $attempt_number -ge 2 ]]; then
        log_success "Mock retry command: succeeded after $attempt_number attempts"
        return 0
    else
        log_warning "Mock retry command: failed on attempt $attempt_number"
        return 1
    fi
}

# Mock sequential iteration processing
execute_iteration_iterate_files_sequential() {
    local pattern="${1:-*}"
    log_info "Mock sequential iteration: processing files matching '$pattern'"
    
    # Simulate file processing
    sleep 0.5
    local files=("file1.txt" "file2.txt" "file3.txt")
    
    for file in "${files[@]}"; do
        log_info "Processing file: $file"
        sleep 0.5
    done
    
    log_success "Sequential iteration completed: processed ${#files[@]} files"
    return 0
}

# Mock fallback path execution for testing
execute_fallback_path() {
    local path_id="${1}"
    log_info "Mock fallback path execution: $path_id"
    
    # Simulate work
    sleep 1
    
    # Simulate success for primary_service_call, failure for others to test fallback behavior
    case "$path_id" in
        "primary_service_call")
            log_success "Primary service call succeeded"
            return 0
            ;;
        "secondary_service_call") 
            log_warning "Secondary service call failed"
            return 1
            ;;
        "cache_fallback_call")
            log_warning "Cache fallback failed"
            return 1
            ;;
        "default_response_call")
            log_success "Default response call succeeded"
            return 0
            ;;
        *)
            log_info "Unknown fallback path succeeded: $path_id"
            return 0
            ;;
    esac
}

# Workflow Execution

# Node: initialize_validation
echo "🔍 Initializing Data Validation & Cleanup System"
echo "========================================="

# Create validation workspace
mkdir -p /tmp/data_validation
mkdir -p /tmp/data_validation/input
mkdir -p /tmp/data_validation/output
mkdir -p /tmp/data_validation/reports
mkdir -p /tmp/data_validation/backups

# Initialize validation metadata
VALIDATION_ID="val_$(date +%s)"
CURRENT_TIME=$(date -Iseconds)

echo "🆔 Validation ID: \$VALIDATION_ID" 
echo "⏰ Start Time: \$CURRENT_TIME"
echo "📊 Data Source: $(get_var "INPUT_DATA_SOURCE" "initialize_validation")"
echo "🔧 Validation Rules: $(get_var "VALIDATION_RULES" "initialize_validation")"
echo "🧹 Cleanup Actions: $(get_var "CLEANUP_ACTIONS" "initialize_validation")"
echo "📝 Output Format: $(get_var "OUTPUT_FORMAT" "initialize_validation")"
echo "🚫 Error Threshold: $(get_var "ERROR_THRESHOLD" "initialize_validation")%"

# Save configuration
echo "\$VALIDATION_ID" > /tmp/data_validation/validation_id.txt
echo "$(get_var "INPUT_DATA_SOURCE" "initialize_validation")" > /tmp/data_validation/input_source.txt
echo "$(get_var "DATA_CONTENT" "initialize_validation")" > /tmp/data_validation/input/raw_data.txt
echo "$(get_var "VALIDATION_RULES" "initialize_validation")" > /tmp/data_validation/validation_rules.txt
echo "$(get_var "CLEANUP_ACTIONS" "initialize_validation")" > /tmp/data_validation/cleanup_actions.txt

echo "✅ Validation environment initialized successfully"


# Node: analyze_data_structure
# Function to validate and extract content from API response
extract_llm_content() {
    local response="$1"
    if [[ -n "$response" ]] && echo "$response" | jq -e '.choices[0].message.content' >/dev/null 2>&1; then
        echo "$response" | jq -r '.choices[0].message.content'
        return 0
    else
        return 1
    fi
}

# Three-stage LLM fallback: OpenAI -> LLMv7 -> Demo
llm_response=""
llm_content=""

# Stage 1: Try OpenAI if API key is available
if [[ -n "${OPENAI_API_KEY:-}" ]]; then
    log_info "Using OpenAI API..."
    llm_response=$(curl -s -X POST "https://api.openai.com/v1/chat/completions" \
      -H "Authorization: Bearer $OPENAI_API_KEY" \
      -H "Content-Type: application/json" \
      -d '{"model": "gpt-4", "messages": [{"role": "user", "content": "Hello"}]}' \
      --connect-timeout 30 --max-time 60)
    if extract_llm_content "$llm_response" >/dev/null 2>&1; then
        llm_content=$(extract_llm_content "$llm_response")
        log_info "OpenAI API successful"
    else
        log_warning "OpenAI API failed, trying LLMv7..."
    fi
fi

# Stage 2: Try LLMv7 if OpenAI failed or no key available
if [[ -z "$llm_content" ]]; then
    if [[ -z "${OPENAI_API_KEY:-}" ]]; then
        log_info "OPENAI_API_KEY not set, using LLMv7..."
    fi
    
    llm_response=$(curl -s -X POST "https://api.llm7.io/v1/chat/completions" \
      -H "Content-Type: application/json" \
      -d '{"model": "default", "messages": [{"role": "user", "content": "Hello"}]}' \
      --connect-timeout 30 --max-time 60)
    if extract_llm_content "$llm_response" >/dev/null 2>&1; then
        llm_content=$(extract_llm_content "$llm_response")
        log_info "LLMv7 API successful"
    else
        log_warning "LLMv7 API also failed, using mock response"
    fi
fi

# Stage 3: Final fallback to demo response
if [[ -z "$llm_content" ]]; then
    llm_content="Mock LLM Response: This is a simulated response because all API calls failed. Original prompt was: Hello"
    log_warning "Using mock response as final fallback"
fi

# Store the content in workflow variable for other nodes to reference
set_workflow_var "llm_content" "$llm_content"
set_workflow_var "llm_success" "true"

# Output the final content
echo "$llm_content"

# Node: perform_initial_validation
echo "🔍 Performing Initial Data Validation"
echo "====================================="

RAW_DATA="$(get_var "DATA_CONTENT" "perform_initial_validation")"
VALIDATION_RULES="$(get_var "VALIDATION_RULES" "perform_initial_validation")"

# Initialize counters
TOTAL_RECORDS=0
VALID_RECORDS=0
ERROR_COUNT=0
WARNINGS_COUNT=0

# Count total records (assuming CSV-like format)
TOTAL_RECORDS=$(echo "\$RAW_DATA" | grep -c ';' || echo "1")
echo "📊 Total Records Found: \$TOTAL_RECORDS"

# Validate email formats if rule is active
if echo "\$VALIDATION_RULES" | grep -q "email_format"; then
  echo "✉️ Validating email formats..."
  INVALID_EMAILS=$(echo "\$RAW_DATA" | grep -o '[^,;]*@[^,;]*' | grep -v '@.*\.' | wc -l)
  ERROR_COUNT=$((ERROR_COUNT + INVALID_EMAILS))
  echo "   Found \$INVALID_EMAILS invalid email formats"
fi

# Check for required fields if rule is active
if echo "\$VALIDATION_RULES" | grep -q "required_fields"; then
  echo "📋 Checking required fields..."
  EMPTY_FIELDS=$(echo "\$RAW_DATA" | grep -o ',,' | wc -l)
  MISSING_EMAILS=$(echo "\$RAW_DATA" | grep -o ',[[:space:]]*,' | wc -l)
  MISSING_COUNT=$((EMPTY_FIELDS + MISSING_EMAILS))
  ERROR_COUNT=$((ERROR_COUNT + MISSING_COUNT))
  echo "   Found \$MISSING_COUNT missing required fields"
fi

# Check data completeness if rule is active
if echo "\$VALIDATION_RULES" | grep -q "data_completeness"; then
  echo "📈 Checking data completeness..."
  # Simple completeness check
  INCOMPLETE_RECORDS=$(echo "\$RAW_DATA" | grep -c ',,' || echo "0")
  WARNINGS_COUNT=$((WARNINGS_COUNT + INCOMPLETE_RECORDS))
  echo "   Found \$INCOMPLETE_RECORDS potentially incomplete records"
fi

# Calculate error percentage
if [ "\$TOTAL_RECORDS" -gt 0 ]; then
  ERROR_PERCENTAGE=$(( (ERROR_COUNT * 100) / TOTAL_RECORDS ))
else
  ERROR_PERCENTAGE=100
fi

VALID_RECORDS=$((TOTAL_RECORDS - ERROR_COUNT))

echo ""
echo "📊 Validation Summary:"
echo "   Total Records: \$TOTAL_RECORDS"
echo "   Valid Records: \$VALID_RECORDS"
echo "   Errors Found: \$ERROR_COUNT"
echo "   Warnings: \$WARNINGS_COUNT"
echo "   Error Rate: $(get_var "ERROR_PERCENTAGE" "perform_initial_validation")%"
echo "   Error Threshold: $(get_var "ERROR_THRESHOLD" "perform_initial_validation")%"

# Save validation results
echo "\$TOTAL_RECORDS" > /tmp/data_validation/total_records.txt
echo "\$VALID_RECORDS" > /tmp/data_validation/valid_records.txt
echo "\$ERROR_COUNT" > /tmp/data_validation/error_count.txt
echo "\$ERROR_PERCENTAGE" > /tmp/data_validation/error_percentage.txt

if [ "\$ERROR_PERCENTAGE" -gt "$(get_var "ERROR_THRESHOLD" "perform_initial_validation")" ]; then
  echo "❌ Error rate exceeds threshold ($(get_var "ERROR_PERCENTAGE" "perform_initial_validation")% > $(get_var "ERROR_THRESHOLD" "perform_initial_validation")%)"
  echo "VALIDATION_STATUS=FAILED_THRESHOLD" >> /tmp/data_validation/status.txt
else
  echo "✅ Error rate within acceptable threshold"
  echo "VALIDATION_STATUS=PASSED_THRESHOLD" >> /tmp/data_validation/status.txt
fi


# Node: clean_and_normalize
echo "🧹 Starting Data Cleaning and Normalization"
echo "==========================================="

RAW_DATA="$(get_var "DATA_CONTENT" "clean_and_normalize")"
CLEANUP_ACTIONS="$(get_var "CLEANUP_ACTIONS" "clean_and_normalize")"
CLEANED_DATA="\$RAW_DATA"

# Backup original data
echo "\$RAW_DATA" > /tmp/data_validation/backups/original_data.txt

# Apply normalize_text action if specified
if echo "\$CLEANUP_ACTIONS" | grep -q "normalize_text"; then
  echo "🔤 Normalizing text formatting..."
  # Remove extra spaces, normalize case for emails
  CLEANED_DATA=$(echo "\$CLEANED_DATA" | sed 's/[[:space:]]*,[[:space:]]*/,/g' | sed 's/[[:space:]]*;[[:space:]]*/;/g')
  # Convert emails to lowercase
  CLEANED_DATA=$(echo "\$CLEANED_DATA" | sed 's/\([^,;]*@[^,;]*\)/\L\1/g')
  echo "   ✅ Text normalization completed"
fi

# Apply remove_duplicates action if specified
if echo "\$CLEANUP_ACTIONS" | grep -q "remove_duplicates"; then
  echo "🔄 Removing duplicate entries..."
  ORIGINAL_COUNT=$(echo "\$CLEANED_DATA" | grep -c ';' || echo "1")
  CLEANED_DATA=$(echo "\$CLEANED_DATA" | tr ';' '\n' | sort | uniq | tr '\n' ';' | sed 's/;\$//')
  CLEANED_COUNT=$(echo "\$CLEANED_DATA" | grep -c ';' || echo "1")
  REMOVED_DUPLICATES=$((ORIGINAL_COUNT - CLEANED_COUNT))
  echo "   ✅ Removed \$REMOVED_DUPLICATES duplicate entries"
fi

# Apply standardize_formats action if specified
if echo "\$CLEANUP_ACTIONS" | grep -q "standardize_formats"; then
  echo "📏 Standardizing data formats..."
  # Standardize email domains
  CLEANED_DATA=$(echo "\$CLEANED_DATA" | sed 's/@INVALID-EMAIL/@invalid.domain/g')
  # Add placeholder for missing emails
  CLEANED_DATA=$(echo "\$CLEANED_DATA" | sed 's/,,/,placeholder@domain.com,/g')
  echo "   ✅ Format standardization completed"
fi

# Save cleaned data
echo "\$CLEANED_DATA" > /tmp/data_validation/output/cleaned_data.txt

# Calculate improvement metrics
ORIGINAL_ISSUES=$(echo "\$RAW_DATA" | grep -o 'INVALID\|,,' | wc -l)
REMAINING_ISSUES=$(echo "\$CLEANED_DATA" | grep -o 'INVALID\|,,' | wc -l)
IMPROVEMENT=$((ORIGINAL_ISSUES - REMAINING_ISSUES))

echo ""
echo "🎯 Cleaning Results:"
echo "   Original Issues: \$ORIGINAL_ISSUES"
echo "   Remaining Issues: \$REMAINING_ISSUES" 
echo "   Issues Fixed: \$IMPROVEMENT"

echo "CLEANING_IMPROVEMENT=\$IMPROVEMENT" >> /tmp/data_validation/status.txt
echo "✅ Data cleaning completed successfully"


# Node: format_output

# Node: format_output (Format Clean Data Output)
execute_template_transform_format_output() {
    log_step "🔧 Template Transform: Format Clean Data Output"

    local output_var="template_output"
    local template_content=""

    # Inline template content
    template_content=''
    log_debug "Using inline template content"

    # Validate template was resolved
    if [[ -z "$template_content" ]]; then
        log_error "Failed to resolve template content"
        set_workflow_var "$output_var" ""
        return 1
    fi

    log_debug "Template resolved, length: ${#template_content} characters"

    # Apply template parameters (basic substitution)
    local rendered_content="$template_content"

    # No template parameters configured
    log_debug "No template parameters to process"

    # Advanced template functions processing
    rendered_content=$(process_template_functions "$rendered_content")
    
    # Additional variable substitution for workflow variables
    rendered_content=$(substitute_variables "$rendered_content")

    # Set output variable
    set_workflow_var "$output_var" "$rendered_content"

    log_success "Template transformed and stored in $output_var"
    log_debug "Template output length: ${#rendered_content} characters"
}

# Advanced template function processor for node format_output
process_template_functions_format_output() {
    local content="$1"

    # {{#date}} -> current date (YYYY-MM-DD)
    content="${content//\{\{#date\}\}/$(date '+%Y-%m-%d')}"

    # {{#time}} -> current time (HH:MM:SS)
    content="${content//\{\{#time\}\}/$(date '+%H:%M:%S')}"

    # {{#datetime}} -> current date and time (ISO 8601)
    content="${content//\{\{#datetime\}\}/$(date -Iseconds)}"

    # {{#timestamp}} -> current Unix timestamp
    content="${content//\{\{#timestamp\}\}/$(date '+%s')}"

    # {{#uuid}} -> generate UUID (fallback if uuidgen not available)
    if command -v uuidgen >/dev/null 2>&1; then
        content="${content//\{\{#uuid\}\}/$(uuidgen)}"
    else
        # Fallback UUID generation using date and random
        local fallback_uuid="uuid-$(date +%s)-$RANDOM"
        content="${content//\{\{#uuid\}\}/$fallback_uuid}"
    fi

    # {{#random}} -> random number (0-32767)
    content="${content//\{\{#random\}\}/$RANDOM}"

    # {{#hostname}} -> current hostname
    content="${content//\{\{#hostname\}\}/$(hostname 2>/dev/null || echo 'unknown')}"

    # {{#user}} -> current user
    content="${content//\{\{#user\}\}/$(whoami 2>/dev/null || echo 'unknown')}"

    # {{#pwd}} -> current working directory
    content="${content//\{\{#pwd\}\}/$(pwd)}"

    # Process variable-based functions with regex matching
    # {{#base64:variable}} -> base64 encode variable
    while [[ "$content" =~ \{\{#base64:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local encoded_value=""
        
        if [[ -n "$var_value" ]]; then
            if command -v base64 >/dev/null 2>&1; then
                encoded_value="$(echo -n "$var_value" | base64 -w 0)"
            else
                log_warning "base64 command not available, skipping encoding for $var_name"
                encoded_value="$var_value"
            fi
        fi
        
        content="${content//\{\{#base64:$var_name\}\}/$encoded_value}"
    done

    # {{#url_encode:variable}} -> URL encode variable
    while [[ "$content" =~ \{\{#url_encode:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local encoded_value=""
        
        if [[ -n "$var_value" ]]; then
            # Simple URL encoding (encode spaces and special characters)
            encoded_value="$(echo "$var_value" | sed 's/ /%20/g; s/&/%26/g; s/?/%3F/g; s/=/%3D/g')"
        fi
        
        content="${content//\{\{#url_encode:$var_name\}\}/$encoded_value}"
    done

    # {{#upper:variable}} -> uppercase variable
    while [[ "$content" =~ \{\{#upper:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local upper_value=""
        
        if [[ -n "$var_value" ]]; then
            upper_value="$(echo "$var_value" | tr '[:lower:]' '[:upper:]')"
        fi
        
        content="${content//\{\{#upper:$var_name\}\}/$upper_value}"
    done

    # {{#lower:variable}} -> lowercase variable
    while [[ "$content" =~ \{\{#lower:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local lower_value=""
        
        if [[ -n "$var_value" ]]; then
            lower_value="$(echo "$var_value" | tr '[:upper:]' '[:lower:]')"
        fi
        
        content="${content//\{\{#lower:$var_name\}\}/$lower_value}"
    done

    # {{#length:variable}} -> length of variable
    while [[ "$content" =~ \{\{#length:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local length_value="${#var_value}"
        
        content="${content//\{\{#length:$var_name\}\}/$length_value}"
    done

    # {{#json_escape:variable}} -> JSON escape variable
    while [[ "$content" =~ \{\{#json_escape:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local escaped_value=""
        
        if [[ -n "$var_value" ]]; then
            # Basic JSON escaping
            escaped_value="$(echo "$var_value" | sed 's/\\/\\\\/g; s/"/\\"/g; s/\t/\\t/g; s/\n/\\n/g; s/\r/\\r/g')"
        fi
        
        content="${content//\{\{#json_escape:$var_name\}\}/$escaped_value}"
    done

    echo "$content"
}

# Use the node-specific template function processor
process_template_functions() {
    process_template_functions_format_output "$1"
}
execute_template_transform_format_output

# Node: generate_quality_report
# Function to validate and extract content from API response
extract_llm_content() {
    local response="$1"
    if [[ -n "$response" ]] && echo "$response" | jq -e '.choices[0].message.content' >/dev/null 2>&1; then
        echo "$response" | jq -r '.choices[0].message.content'
        return 0
    else
        return 1
    fi
}

# Three-stage LLM fallback: OpenAI -> LLMv7 -> Demo
llm_response=""
llm_content=""

# Stage 1: Try OpenAI if API key is available
if [[ -n "${OPENAI_API_KEY:-}" ]]; then
    log_info "Using OpenAI API..."
    llm_response=$(curl -s -X POST "https://api.openai.com/v1/chat/completions" \
      -H "Authorization: Bearer $OPENAI_API_KEY" \
      -H "Content-Type: application/json" \
      -d '{"model": "gpt-4", "messages": [{"role": "user", "content": "Hello"}]}' \
      --connect-timeout 30 --max-time 60)
    if extract_llm_content "$llm_response" >/dev/null 2>&1; then
        llm_content=$(extract_llm_content "$llm_response")
        log_info "OpenAI API successful"
    else
        log_warning "OpenAI API failed, trying LLMv7..."
    fi
fi

# Stage 2: Try LLMv7 if OpenAI failed or no key available
if [[ -z "$llm_content" ]]; then
    if [[ -z "${OPENAI_API_KEY:-}" ]]; then
        log_info "OPENAI_API_KEY not set, using LLMv7..."
    fi
    
    llm_response=$(curl -s -X POST "https://api.llm7.io/v1/chat/completions" \
      -H "Content-Type: application/json" \
      -d '{"model": "default", "messages": [{"role": "user", "content": "Hello"}]}' \
      --connect-timeout 30 --max-time 60)
    if extract_llm_content "$llm_response" >/dev/null 2>&1; then
        llm_content=$(extract_llm_content "$llm_response")
        log_info "LLMv7 API successful"
    else
        log_warning "LLMv7 API also failed, using mock response"
    fi
fi

# Stage 3: Final fallback to demo response
if [[ -z "$llm_content" ]]; then
    llm_content="Mock LLM Response: This is a simulated response because all API calls failed. Original prompt was: Hello"
    log_warning "Using mock response as final fallback"
fi

# Store the content in workflow variable for other nodes to reference
set_workflow_var "llm_content" "$llm_content"
set_workflow_var "llm_success" "true"

# Output the final content
echo "$llm_content"

# Node: send_quality_notification

# Node: send_quality_notification (Send Quality Report Notification)
execute_telegram_send_quality_notification() {
    log_step "📱 Sending Telegram message: Send Quality Report Notification"

    local message="🔍 Data Validation & Cleanup Report

📊 **Quality Summary:**
- Source: $(get_var "INPUT_DATA_SOURCE" "send_quality_notification")
- Rules Applied: $(get_var "VALIDATION_RULES" "send_quality_notification")
- Status: {{perform_initial_validation.output}}
- Error Threshold: $(get_var "ERROR_THRESHOLD" "send_quality_notification")%

🧹 **Cleaning Results:**
{{clean_and_normalize.output}}

📋 **AI Analysis Summary:**
Key findings from automated analysis

📈 **Next Steps:**
Review detailed quality report for specific recommendations

✅ Data validation and cleanup process completed!
"
    local parse_mode="Markdown"
    local max_retries=3
    local disable_notification=false
    local error_handling="fail"
    

    # Validate message is not empty
    if [[ -z "$message" ]]; then
        log_error "Telegram message content is empty"
        case "$error_handling" in
            "ignore")
                log_info "Ignoring Telegram error as configured"
                return 0
                ;;
            "continue")
                log_warning "Continuing despite Telegram error"
                return 0
                ;;
            *)
                return 1
                ;;
        esac
    fi

    # Use chat_id from node configuration
    local chat_id="$(get_var "TELEGRAM_CHAT_ID" "send_quality_notification")"

    # Use bot_token from node configuration
    local bot_token="$(get_var "TELEGRAM_BOT_TOKEN" "send_quality_notification")"

    # Character escaping functions for Telegram
    escape_json() {
        local text="$1"
        # Escape characters that would break JSON payload
        text="${text//\\/\\\\}"  # Escape backslashes first
        text="${text//"/\\"}"      # Escape double quotes
        text="${text//$'\n'/\\n}"  # Escape newlines
        text="${text//$'\r'/\\r}"  # Escape carriage returns
        text="${text//$'\t'/\\t}"  # Escape tabs
        echo "$text"
    }

    escape_markdown() {
        local text="$1"
        # Escape special MarkdownV2 characters
        text="${text//_/\_}"
        text="${text//*/\*}"
        text="${text//[/\[}"
        text="${text//]/\]}"
        text="${text//(/\(}"
        text="${text//)/\)}"
        text="${text//~/\~}"
        text="${text//\`/\\\`}"
        text="${text//>/\>}"
        text="${text//#/\#}"
        text="${text//+/\+}"
        text="${text//-/\-}"
        text="${text//=/\=}"
        text="${text//|/\|}"
        text="${text//\{/\\{}"
        text="${text//\}/\\}}"
        text="${text//./\.}"
        text="${text//!/\!}"
        echo "$text"
     }

    # Escape message content for JSON payload (but preserve formatting tags)
    local escaped_message
    case "$parse_mode" in
        "HTML")
            # For HTML mode, only escape JSON special characters, not HTML formatting tags
            escaped_message=$(escape_json "$message")
            ;;
        "Markdown"|"MarkdownV2")
            # For Markdown modes, escape markdown then JSON
            local markdown_escaped
            markdown_escaped=$(escape_markdown "$message")
            escaped_message=$(escape_json "$markdown_escaped")
            ;;
        *)
            escaped_message=$(escape_json "$message")
            ;;
    esac

    # Prepare API request payload
    local api_url="https://api.telegram.org/bot$bot_token/sendMessage"
    local payload
    payload=$(cat <<EOF
{
    "chat_id": "$chat_id",
    "text": "$escaped_message",
    "parse_mode": "$parse_mode"
}
EOF
)

    log_debug "Sending message to Telegram API: $api_url"
    log_debug "Payload length: ${#payload} characters"

    # Retry logic with exponential backoff
    local attempt=1
    local delay=1
    
    while [[ $attempt -le $max_retries ]]; do
        log_debug "Telegram API attempt $attempt of $max_retries"
        
        # Make API request
        local response_file=$(mktemp)
        local http_code
        
        http_code=$(curl -s -w "%{http_code}" \
            -X POST \
            -H "Content-Type: application/json" \
            -d "$payload" \
            --connect-timeout 10 \
            --max-time 30 \
            "$api_url" \
            -o "$response_file" 2>/dev/null)
        
        local curl_exit_code=$?
        local response_body=$(cat "$response_file" 2>/dev/null)
        
        # Clean up temp file
        rm -f "$response_file" 2>/dev/null
        
        # Check if request was successful
        if [[ $curl_exit_code -eq 0 && "$http_code" =~ ^2[0-9][0-9]$ ]]; then
            log_success "Telegram message sent successfully (HTTP $http_code)"
            
            # Set success variables
            set_workflow_var "telegram_success" "true"
            set_workflow_var "telegram_http_code" "$http_code"
            set_workflow_var "telegram_response" "$response_body"
            set_workflow_var "telegram_message_sent" "true"
            
            log_debug "Telegram API response: $response_body"
            return 0
        else
            # Log the failure
            if [[ $curl_exit_code -ne 0 ]]; then
                log_warning "Telegram API request failed (curl exit code: $curl_exit_code) - attempt $attempt/$max_retries"
            else
                log_warning "Telegram API returned HTTP $http_code - attempt $attempt/$max_retries"
                if [[ -n "$response_body" ]]; then
                    log_warning "API error response: $response_body"
                fi
            fi
            
            # Check if we should retry
            if [[ $attempt -lt $max_retries ]]; then
                log_info "Retrying in ${delay}s..."
                sleep $delay
                delay=$((delay * 2))  # Exponential backoff
                attempt=$((attempt + 1))
            else
                # Final failure - handle based on error_handling setting
                log_error "Telegram message failed after $max_retries attempts"
                
                # Set failure variables
                set_workflow_var "telegram_success" "false"
                set_workflow_var "telegram_http_code" "${http_code:-0}"
                set_workflow_var "telegram_response" "$response_body"
                set_workflow_var "telegram_message_sent" "false"
                set_workflow_var "telegram_error" "MAX_RETRIES_EXCEEDED"
                
                case "$error_handling" in
                    "ignore")
                        log_info "Ignoring Telegram failure as configured"
                        return 0
                        ;;
                    "continue")
                        log_warning "Continuing despite Telegram failure"
                        return 0
                        ;;
                    *)
                        return 1
                        ;;
                esac
            fi
        fi
    done
}
execute_telegram_send_quality_notification

# Node: final_summary
echo ""

echo "Workflow completed successfully"
exit 0
